query venueMetaImage($venueSlug: String!) {
  guestVenue(slug: $venueSlug) {
    id
    ogImage(transform: 
"og") {
      id
      originalImagePath
      originalImageUrl
      __typename
    }
    image: ogImage {
      id
      originalImageUrl
      __typename
    }
    __typename
  }
}

query currentUser {
  currentUser {
    ...UserParts
    __typename
  }
}
fragment UserParts on User {
  id
  name
  email
  receiptEmail
  isOver18
  mobile
  savePaymentDetails
  __typename
}

query cartTableInfo($venueSlug: String!, $orderingType: OrderingType!, $tableNumber: String, $tableArea: String, $googlePlaceId: String) {
  getCart(
    slug: $venueSlug
    orderingType: $orderingType
    tableNumber: $tableNumber
    tableArea: $tableArea
    googlePlaceId: $googlePlaceId
  ) {
    tableNumber
    tableArea
    orderingWindowStartDate
    __typename
  }
}

